    ___root_globals_partition(___GLO_SUBLIST_COUNT,id,owners,&lo,&hi);
    for(i=lo;i<hi && cells[id]==0;i++) {
      ___glo_struct *g=___GSTATE->mem.glo_list.sublist[i].head;
      for(;g!=0;g=g->next) if(g->val==___UNB1) {cells[id]=&g->val;break;}
