                   arguments: '("-:p1" "--process-bytes") stderr-redirection: #t char-encoding: 'ISO-8859-1)))
         (bytes (let loop ((xs '())) (let ((b (read-u8 port)))
                   (if (eof-object? b) (reverse xs) (loop (cons b xs)))))))
