    (if (and (= (process-fd 6 0) 1) (< fd 0)) (error "descriptor probe allocation failed"))
    (if (< fd 0) (display "PROCESS-POSIX-DESCRIPTORS-UNAVAILABLE\n"))
    (if (>= fd 0)
